public class Main {
    static List<int[]>[] adj;
    static int[] disc, low;
    static boolean[] visited;
    static int timer = 0;
    static List<int[]> bridges = new ArrayList<>();

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int V = sc.nextInt();
        int E = sc.nextInt();

        adj = new ArrayList[V];
        for (int i = 0; i < V; i++) {
            adj[i] = new ArrayList<>();
        }

        for (int i = 0; i < E; i++) {
            int u = sc.nextInt();
            int v = sc.nextInt();
            adj[u].add(new int[]{v, i});
            adj[v].add(new int[]{u, i});
        }

        disc = new int[V];
        low = new int[V];
        visited = new boolean[V];

        for (int i = 0; i < V; i++) {
            if (!visited[i]) {
                dfs(i, -1);
            }
        }

        // Sort bridges: first by min endpoint, then by max endpoint
        bridges.sort((a, b) -> {
            int minA = Math.min(a[0], a[1]);
            int minB = Math.min(b[0], b[1]);
            if (minA != minB) return minA - minB;
            int maxA = Math.max(a[0], a[1]);
            int maxB = Math.max(b[0], b[1]);
            return maxA - maxB;
        });

        StringBuilder sb = new StringBuilder();
        for (int[] bridge : bridges) {
            int u = Math.min(bridge[0], bridge[1]);
            int v = Math.max(bridge[0], bridge[1]);
            sb.append(u).append(" ").append(v).append("\n");
        }

        System.out.print(sb);
    }

    static void dfs(int u, int parentEdgeId) {
        visited[u] = true;
        disc[u] = low[u] = timer++;

        for (int[] next : adj[u]) {
            int v = next[0];
            int edgeId = next[1];

