public class Main {
    static class FastScanner {
        private final InputStream in = System.in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        int nextInt() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);

            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }

            int val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }
    }

    static class Edge {
        int to, id;
        Edge(int to, int id) {
            this.to = to;
            this.id = id;
        }
    }

    static int n, m;
    static List<Edge>[] graph;
    static int[] tin, low;
    static boolean[] visited;
    static int timer = 0;
    static int[] eu, ev;
    static List<int[]> bridges = new ArrayList<>();

    static void dfs(int v, int parentEdge) {
        visited[v] = true;
        tin[v] = low[v] = timer++;

        for (Edge e : graph[v]) {
            if (e.id == parentEdge) continue;
            int to = e.to;

            if (visited[to]) {
                low[v] = Math.min(low[v], tin[to]);
            } else {
                dfs(to, e.id);
                low[v] = Math.min(low[v], low[to]);
                if (low[to] > tin[v]) {
                    int a = eu[e.id];
                    int b = ev[e.id];
                    if (a > b) {
                        int tmp = a;
                        a = b;
                        b = tmp;
                    }
                    bridges.add(new int[]{a, b});
                }
            }
        }
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner();

        n = fs.nextInt();
        m = fs.nextInt();

        graph = new ArrayList[n];
        for (int i = 0; i < n; i++) graph[i] = new ArrayList<>();

        eu = new int[m];
        ev = new int[m];

        for (int i = 0; i < m; i++) {
            int u = fs.nextInt();
            int v = fs.nextInt();
            eu[i] = u;
            ev[i] = v;
            graph[u].add(new Edge(v, i));
            graph[v].add(new Edge(u, i));
        }

        tin = new int[n];
        low = new int[n];
        visited = new boolean[n];

        for (int i = 0; i < n; i++) {
            if (!visited[i]) dfs(i, -1);
        }

        bridges.sort((x, y) -> {
            if (x[0] != y[0]) return Integer.compare(x[0], y[0]);
            return Integer.compare(x[1], y[1]);
        });

        StringBuilder sb = new StringBuilder();
        for (int[] b : bridges) {
            sb.append(b[0]).append(' ').append(b[1]).append('\n');
        }

        System.out.print(sb.toString());
    }
}

