int head[MAXN];
int edge_cnt;

int disc[MAXN], low[MAXN], visited[MAXN];
int time_counter;
int bridge_count;
int bridge_u[MAXM], bridge_v[MAXM]; // store bridges

int cmp(const void *a, const void *b) {
    int u1 = *(int*)a;
    int v1 = *((int*)a + 1);
    int u2 = *(int*)b;
    int v2 = *((int*)b + 1);
    if (u1 != u2) return u1 - u2;
    return v1 - v2;
}

void add_edge(int u, int v, int id) {
    edges[edge_cnt].to = v;
    edges[edge_cnt].next = head[u];
    edges[edge_cnt].id = id;
    head[u] = edge_cnt++;

    edges[edge_cnt].to = u;
    edges[edge_cnt].next = head[v];
    edges[edge_cnt].id = id;
    head[v] = edge_cnt++;
}

void dfs(int u, int parent_edge) {
    visited[u] = 1;
    disc[u] = low[u] = ++time_counter;

    for (int e = head[u]; e != -1; e = edges[e].next) {
        int v = edges[e].to;
        int edge_id = edges[e].id;

        if (edge_id == parent_edge) continue;

        if (!visited[v]) {
            dfs(v, edge_id);
            low[u] = (low[u] < low[v]) ? low[u] : low[v];

            if (low[v] > disc[u]) {
                // bridge found
                int a = u, b = v;
                if (a > b) {
                    int tmp = a; a = b; b = tmp;
                }
                bridge_u[bridge_count] = a;
                bridge_v[bridge_count] = b;
                bridge_count++;
            }
        } else {
            low[u] = (low[u] < disc[v]) ? low[u] : disc[v];
        }
    }
}

