typedef struct Edge {
    int to;
    int id;
    int next;
} Edge;

typedef struct Pair {
    int a, b;
} Pair;

int cmp_pair(const void *p1, const void *p2) {
    const Pair *x = (const Pair *)p1;
    const Pair *y = (const Pair *)p2;
    if (x->a != y->a) return x->a - y->a;
    return x->b - y->b;
}

void dfs(int u, int parentEdge,
         int *head, Edge *edges,
         int *visited, int *disc, int *low, int *timer,
         Pair *bridges, int *bridgeCount) {
    visited[u] = 1;
    disc[u] = low[u] = ++(*timer);

    for (int e = head[u]; e != -1; e = edges[e].next) {
        int v = edges[e].to;
        int id = edges[e].id;

        if (id == parentEdge) continue;

        if (!visited[v]) {
            dfs(v, id, head, edges, visited, disc, low, timer, bridges, bridgeCount);
            if (low[v] < low[u]) low[u] = low[v];

            if (low[v] > disc[u]) {
                int a = u < v ? u : v;
                int b = u < v ? v : u;
                bridges[*bridgeCount].a = a;
                bridges[*bridgeCount].b = b;
                (*bridgeCount)++;
            }
        } else {
            if (disc[v] < low[u]) low[u] = disc[v];
        }
    }
}

