class BridgeFinder {
    int n;
    vector<vector<int>> adj;
    vector<pair<int,int>> edges;
    vector<int> tin, low;
    vector<bool> visited;
    int timer;
    vector<pair<int,int>> bridges;

public:
    BridgeFinder(int nodes, const vector<pair<int,int>>& edgeList) {
        n = nodes;
        edges = edgeList;
        adj.resize(n);
        for (auto &[u, v] : edges) {
            adj[u].push_back(v);
            adj[v].push_back(u);
        }
        tin.assign(n, -1);
        low.assign(n, -1);
        visited.assign(n, false);
        timer = 0;
    }

    void dfs(int v, int p = -1) {
        visited[v] = true;
        tin[v] = low[v] = timer++;
        for (int to : adj[v]) {
            if (to == p) continue;
            if (visited[to]) {
                low[v] = min(low[v], tin[to]);
            } else {
                dfs(to, v);
                low[v] = min(low[v], low[to]);
                if (low[to] > tin[v]) {
                    bridges.push_back({min(v, to), max(v, to)});
                }
            }
        }
    }

    vector<pair<int,int>> findBridges() {
        for (int i = 0; i < n; ++i) {
            if (!visited[i]) {
                dfs(i);
            }
        }
        sort(bridges.begin(), bridges.end());
        return bridges;
    }
};

