import sys
sys.setrecursionlimit(10 ** 6)

def find_bridges(n, edges):
    adj = [[] for _ in range(n)]
    for idx, (u, v) in enumerate(edges):
        adj[u].append((v, idx))
        adj[v].append((u, idx))

    visited = [False] * n
    tin = [-1] * n
    low = [-1] * n
    timer = 0
    bridges = []

    def dfs(v, p_edge):
        nonlocal timer
        visited[v] = True
        tin[v] = low[v] = timer
        timer += 1

        for to, edge_id in adj[v]:
            if edge_id == p_edge:
                continue
            if visited[to]:
                low[v] = min(low[v], tin[to])
            else:
                dfs(to, edge_id)
                low[v] = min(low[v], low[to])
                if low[to] > tin[v]:
                    bridges.append(edge_id)

    for i in range(n):
        if not visited[i]:
            dfs(i, -1)

    result = []
    for idx in bridges:
        u, v = edges[idx]
        if u > v:
            u, v = v, u
        result.append((u, v))
    result.sort()
    return result

